SELECT p.id, p.product_name AS productName, p.price, p.stock, p.status, p.description, p.image_url AS imageUrl, c.name AS categoryName FROM product p LEFT JOIN category c ON p.category_id = c.id
p.merchant_id = #{merchantId} AND p.is_deleted = 0
AND p.status = #{status}
AND p.category_id = #{categoryId}
